<script setup lang="ts">import {computed} from 'vue';import {fixed} from '../utils/format';const props=defineProps<{result:any}>();const bins=computed(()=>props.result.empirical.bins.filter((b:any)=>b.count>0));const ymax=computed(()=>Math.max(.1,...bins.value.map((b:any)=>b.semivariance),...props.result.model.curve.map((p:any)=>p.semivariance))*1.12);const maxCount=computed(()=>Math.max(1,...bins.value.map((b:any)=>b.count)));const X=(v:number)=>45+v/props.result.empirical.max_distance*570;const Y=(v:number)=>240-v/ymax.value*205</script><template><div class="variogram-plot"><svg viewBox="0 0 660 290" role="img" aria-label="经验半变异分箱与锁定指数模型"><g v-for="t in [0,.25,.5,.75,1]" :key="t"><line x1="45" x2="615" :y1="35+t*205" :y2="35+t*205" class="map-grid"/><text x="1" :y="39+t*205">{{fixed(ymax*(1-t),1)}}</text><text :x="45+t*570" y="264" text-anchor="middle">{{fixed(result.empirical.max_distance*t,0)}}</text></g><polyline :points="result.model.curve.filter((p:any)=>p.distance>0).map((p:any)=>X(p.distance)+','+Y(p.semivariance)).join(' ')" class="model-curve"/><circle :cx="X(0)" :cy="Y(0)" r="3" class="origin-point"/><circle v-for="b in bins" :key="b.index" :cx="X(b.distance)" :cy="Y(b.semivariance)" :r="3+Math.sqrt(b.count/maxCount)*5" :class="b.used?'bin-point':'unused-bin'"><title>{{b.count}}对 · {{b.used?'用于拟合':'未达计数门槛'}}</title></circle><text x="330" y="286" text-anchor="middle">距离米 / 半方差为百分点²</text></svg><div class="map-legend"><span>● 经验箱（大小=计数）</span><span>— 锁定指数模型</span><span>γ(0)=0；非零距离含nugget</span></div></div></template>
